// ES5 (2009)   - strict mode, JSON, Array.forEach/map/filter/reduce
// ES6 / ES2015 - let/const, arrow function, class, Promise,
//                template literals, destrukturyzacja, spread, modul ES
// ES2017        - async/await, Object.entries/values
// ES2019        - Array.flat/flatMap, Object.fromEntries
// ES2020        - BigInt, ?? (nullish coalescing), ?. (optional chaining)
// ES2021        - Promise.any, String.replaceAll
// ES2022        - Array.at(), Object.hasOwn(), prywatne pola #pole

function bezpiecznePosortuj(tablica) {
  if (typeof tablica.toSorted === "function") {
    return tablica.toSorted(); // nowoczesna, niemutujaca metoda (ES2023)
  }
  return [...tablica].sort(); // fallback - kopia przez spread + zwykly sort
}

function zlePosortuj(tablica) {
  return tablica.toSorted(); // ZLE - brak sprawdzenia, czy metoda istnieje
}
// u uzytkownika ze starsza przegladarka: TypeError: tablica.toSorted is not a function

function dobrzePosortuj(tablica) {
  if (typeof tablica.toSorted === "function") {
    return tablica.toSorted(); // DOBRZE - nowoczesna sciezka
  }
  return [...tablica].sort(); // fallback dla starszych przegladarek
}

exercises.solution:
function bezpiecznePosortuj(tablica) {
  if (typeof tablica.toSorted === "function") {
    return tablica.toSorted();
  }
  return [...tablica].sort();
}

console.log(bezpiecznePosortuj([3, 1, 2])); // [1, 2, 3]

const tablica = [10, 20, 30];

console.log(tablica.at(-1));               // 30
console.log(tablica[tablica.length - 1]);  // 30 - ten sam wynik, starszy zapis

// ECMAScript to formalna specyfikacja - dokument opisujacy zasady
// jezyka, zatwierdzany co roku przez organizacje TC39. JavaScript to
// NAJPOPULARNIEJSZA implementacja tej specyfikacji, uruchamiana w
// przegladarkach (V8 w Chrome, SpiderMonkey w Firefox) i w Node.js.
// Kazda przegladarka implementuje ECMAScript we wlasnym silniku, wiec
// wsparcie dla najnowszych funkcji jezyka moze sie roznic miedzy nimi.

// Nie wszyscy uzytkownicy korzystaja z najnowszych przegladarek - czesc
// moze uzywac starszych wersji, ktore nie implementuja jeszcze swiezo
// wydanych funkcji jezyka. Uzycie takiej funkcji bez sprawdzenia
// wsparcia (np. na caniuse.com) moze spowodowac, ze aplikacja 'wysypie
// sie' z bledem TypeError u czesci uzytkownikow, mimo ze u dewelopera
// (z nowoczesna przegladarka) dzialala bez zarzutu.

console.log(Object.hasOwn({ a: 1 }, "a"));
console.log(Object.hasOwn({ a: 1 }, "toString"));
// true
// false - toString jest odziedziczone z Object.prototype, nie jest wlasna wlasciwoscia

function pobierzOstatni(tablica) {
  return tablica.at(-1);
}
console.log(pobierzOstatni([10, 20, 30]));
// 30

const liczby = [5, 2, 8, 1];
console.log(liczby.toSorted());
console.log(liczby);
// [ 1, 2, 5, 8 ]
// [ 5, 2, 8, 1 ]

const tekst = "kot i kot i kot";
console.log(tekst.replace("kot", "pies"));
console.log(tekst.replaceAll("kot", "pies"));
// "pies i kot i kot"
// "pies i pies i pies"

function bezpiecznyAt(tablica, indeks) {
  if (typeof tablica.at === "function") {
    return tablica.at(indeks);
  }
  return indeks < 0 ? tablica[tablica.length + indeks] : tablica[indeks];
}
console.log(bezpiecznyAt([10, 20, 30], -1));
// 30

// JSON.stringify/parse oraz forEach/map/filter/reduce pochodza z ES5
// (2009) - to jeszcze starsza wersja niz ES6 (2015), z ktorej pochodza
// let/const. Sa wiec szeroko wspierane jeszcze dluzej niz nowoczesne
// funkcje z tego kursu i nie wymagaja zadnej ostroznosci.

const pary = [["imie", "Ala"], ["wiek", 30]];
console.log(Object.fromEntries(pary));
// { imie: "Ala", wiek: 30 }

// Transpilacja to automatyczne "tlumaczenie" nowoczesnego kodu
// JavaScript (np. z arrow function, destrukturyzacja) na starsza
// skladnie, ktora dziala rowniez w bardzo starych przegladarkach.
// Narzedzia takie jak Babel pozwalaja programiscie pisac nowoczesny,
// czytelny kod, a produkcyjna wersje aplikacji generuja juz w wersji
// kompatybilnej wstecz - bez potrzeby recznego pisania fallbackow
// dla kazdej nowej funkcji jezyka z osobna.

const litery = ["a", "b", "c"];
const odwrocone = litery.toReversed();
console.log(odwrocone);
console.log(litery);
// [ "c", "b", "a" ]
// [ "a", "b", "c" ]

function policzWlasneWlasciwosci(obiekt, klucze) {
  return klucze.filter((k) => Object.hasOwn(obiekt, k)).length;
}
console.log(policzWlasneWlasciwosci({ a: 1, b: 2 }, ["a", "b", "c", "toString"]));
// 2

const kontener = { dane: [3, 1, 2] };
console.log(typeof kontener.toSorted === "function");
// false - to zwykly obiekt, a nie tablica, wiec nie ma metody toSorted
// (ktora nalezy do Array.prototype). Trzeba by wywolac kontener.dane.toSorted().

const zagniezdzona = [1, [2, [3, [4, [5]]]]];
console.log(zagniezdzona.flat(Infinity));
console.log(zagniezdzona.flat(1));
// [ 1, 2, 3, 4, 5 ]
// [ 1, 2, [ 3, [ 4, [Array] ] ] ]

// W projekcie wewnetrznym (np. narzedzie dla wlasnych pracownikow)
// znamy dokladnie, jakich przegladarek uzywaja odbiorcy - czesto sa to
// aktualne, nowoczesne wersje, wiec nowa funkcja jak toSorted (ES2023)
// jest bezpieczna. W publicznej aplikacji dla masowego, miedzynarodowego
// odbiorcy czesc uzytkownikow moze korzystac ze starszych przegladarek
// lub urzadzen, ktore jeszcze nie zaimplementowaly tak swiezej funkcji -
// tam warto sprawdzic wsparcie na caniuse.com lub przygotowac fallback.

function bezpiecznyReplaceAll(tekst, szukane, zamiana) {
  if (typeof tekst.replaceAll === "function") {
    return tekst.replaceAll(szukane, zamiana);
  }
  return tekst.split(szukane).join(zamiana);
}
console.log(bezpiecznyReplaceAll("a-b-a-b", "a", "x"));
// "x-b-x-b"

const tablica = [1, 2, 3];
console.log(tablica.at(10));
// undefined - tak samo jak tablica[10], po prostu nie ma elementu pod tym indeksem

// ES5 (2009)   - strict mode, JSON, forEach/map/filter/reduce
// ES6 (2015)   - let/const, arrow function, class, Promise
// ES2020        - BigInt, ?? (nullish coalescing), ?. (optional chaining)
// ES2023        - toSorted/toReversed (niemutujace odpowiedniki sort/reverse)

const tablica = [10, 20, 30];
console.log(Object.hasOwn(tablica, 1));
console.log(Object.hasOwn(tablica, 5));
// true
// false - tablice w JavaScript to specjalne obiekty, a indeksy to ich wlasne klucze

function bezpiecznePodwojSortowanie(tablica) {
  const rosnaco = tablica.toSorted((a, b) => a - b);
  const malejaco = tablica.toSorted((a, b) => b - a);
  return [rosnaco, malejaco];
}
console.log(bezpiecznePodwojSortowanie([3, 1, 2]));
// [ [ 1, 2, 3 ], [ 3, 2, 1 ] ]

const liczby = [1, 2, 3];
console.log(liczby.with(1, 99));
console.log(liczby);
// [ 1, 99, 3 ]
// [ 1, 2, 3 ]

